const $=s=>document.querySelector(s),money=n=>(Math.round((n+Number.EPSILON)*100)/100).toLocaleString('pt-BR',{style:'currency',currency:'BRL'}),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={home:'M3 10 12 3l9 7M5 9v12h14V9M9 21v-7h6v7',bag:'M5 7h14l2 14H3L5 7ZM9 7V5a3 3 0 0 1 6 0v2',box:'m3 7 9-4 9 4v10l-9 4-9-4V7Zm0 0 9 4 9-4M12 11v10M7 5l10 4',calendar:'M4 5h16v16H4V5ZM8 3v4M16 3v4M4 10h16M8 14h2M14 14h2M8 18h2',truck:'M2 5h12v12H2V5ZM14 9h4l4 5v3h-8M5 17a2 2 0 1 0 0 4 2 2 0 0 0 0-4Zm13 0a2 2 0 1 0 0 4 2 2 0 0 0 0-4Z',users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M9 3a4 4 0 1 0 0 8 4 4 0 0 0 0-8ZM17 4a4 4 0 0 1 0 8M22 21v-2a4 4 0 0 0-3-4',wallet:'M3 5h16v4M3 5v15h18V9H3V5ZM17 13v3',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8ZM9 3h6l1 3 3 1 2 5-2 5-3 1-1 3H9l-1-3-3-1-2-5 2-5 3-1 1-3Z',search:'m21 21-6-6M10 3a7 7 0 1 0 0 14 7 7 0 0 0 0-14Z',plus:'M12 5v14M5 12h14',chevron:'m9 5 7 7-7 7',arrow:'M7 17 17 7M7 7h10v10',bell:'M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9ZM10 21h4',paw:'M7 13c-2 2-3 6 0 7 2 1 3-1 5-1s3 2 5 1c3-1 2-5 0-7-3-4-7-4-10 0ZM4 6c-2 0-2 5 0 5s2-5 0-5ZM9 2c-2 0-2 6 0 6s2-6 0-6ZM15 2c-2 0-2 6 0 6s2-6 0-6ZM20 6c-2 0-2 5 0 5s2-5 0-5',clock:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18ZM12 7v5l3 2',check:'m5 12 4 4L19 6',barcode:'M3 4v16M6 4v16M10 4v16M13 4v16M15 4v16M19 4v16M22 4v16',logout:'M9 4H3v16h6M12 12h10m-4-4 4 4-4 4',download:'M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4',menu:'M4 6h16M4 12h16M4 18h16',close:'m6 6 12 12M18 6 6 18',scissors:'m4 4 16 16M4 20 20 4M5 3a3 3 0 1 0 0 6 3 3 0 0 0 0-6ZM5 15a3 3 0 1 0 0 6 3 3 0 0 0 0-6',chart:'M4 3v18h17M8 16v-5M13 16V7M18 16v-8'};
