const btn=(label,action,cls='',ic='')=>`<button ${!label?'aria-label="'+({bell:'Notificações',chevron:'Ver detalhes',close:'Fechar',menu:'Abrir menu'}[ic]||'Abrir')+'"':''} class="${cls}" onclick="${action}">${ic?icon(ic):''}${label}</button>`;
